insert into category_three.question_bank (id, prompt, theme, answers, sort_order, version)
select r->>'id', r->>'prompt', r->>'theme', array(select jsonb_array_elements_text(r->'answers')), (r->>'sort_order')::int, r->>'version'
from jsonb_array_elements('[{"id":"funny-151","prompt":"Your body is constantly shaking hands with the environment. How?","theme":"Nature, Ecology & Interdependence","answers":["Breathing","Eating","Touching","Moving"],"sort_order":151,"version":"funny"},{"id":"funny-152","prompt":"If a city actually listened to human bodies, what would it add first?","theme":"Nature, Ecology & Interdependence","answers":["Walkable streets","More shade","Quiet areas","Public seating"],"sort_order":152,"version":"funny"},{"id":"funny-153","prompt":"A gadget looks clean and futuristic. Where might its ecological mess be hiding?","theme":"Nature, Ecology & Interdependence","answers":["Production happens far away","Energy use is invisible","Products are disposable","Waste is outsourced"],"sort_order":153,"version":"funny"},{"id":"funny-154","prompt":"If freedom is interdependent, what does your freedom secretly need from everyone else?","theme":"Nature, Ecology & Interdependence","answers":["Healthy surroundings","Other people","Public infrastructure","Stable ecosystems"],"sort_order":154,"version":"funny"},{"id":"funny-155","prompt":"What shared resource do people ignore until suddenly everyone is talking about it?","theme":"Nature, Ecology & Interdependence","answers":["Air","Water","Soil","Public space"],"sort_order":155,"version":"funny"},{"id":"funny-156","prompt":"What happens when nature gets treated like an unlimited vending machine?","theme":"Nature, Ecology & Interdependence","answers":["More extraction","More neglect","More simplification","More unequal benefits"],"sort_order":156,"version":"funny"},{"id":"funny-157","prompt":"What turns ''using nature'' into actually having a relationship with it?","theme":"Nature, Ecology & Interdependence","answers":["Care","Restraint","Restoration","Sharing"],"sort_order":157,"version":"funny"},{"id":"funny-158","prompt":"What makes a place feel alive rather than merely occupied?","theme":"Nature, Ecology & Interdependence","answers":["Different kinds of people","Plants and animals","Changing seasons","Communal activity"],"sort_order":158,"version":"funny"},{"id":"funny-159","prompt":"When is being environmentally responsible easiest to keep doing?","theme":"Nature, Ecology & Interdependence","answers":["When it is collective","When it is practical","When it is local","When it is supported"],"sort_order":159,"version":"funny"},{"id":"funny-160","prompt":"Your body enters a stressful environment before your brain admits it. What gives it away?","theme":"Nature, Ecology & Interdependence","answers":["Energy level","Sense of calm","Alertness","Need for daylight"],"sort_order":160,"version":"funny"},{"id":"funny-161","prompt":"A cause is important, but everyone is miserable. What ingredient is missing?","theme":"Joy, Resistance & Collective Change","answers":["Growth","Connection","Relief","Possibility"],"sort_order":161,"version":"funny"},{"id":"funny-162","prompt":"When does ''saving the world'' become a very effective way to destroy your weekend?","theme":"Joy, Resistance & Collective Change","answers":["Guilt drives it","The work never ends","Relationships are neglected","Wins are ignored"],"sort_order":162,"version":"funny"},{"id":"funny-163","prompt":"Why can a tiny win feel like someone plugged the whole group back into a charger?","theme":"Joy, Resistance & Collective Change","answers":["It proves change is possible","It builds trust","It teaches skills","It restores energy"],"sort_order":163,"version":"funny"},{"id":"funny-164","prompt":"What reliably turns a serious crowd into a joyful one?","theme":"Joy, Resistance & Collective Change","answers":["Music","Food","Laughter","Movement"],"sort_order":164,"version":"funny"},{"id":"funny-165","prompt":"When does hope stop being a poster slogan and become something useful?","theme":"Joy, Resistance & Collective Change","answers":["The goal is specific","The action is shared","Progress is visible","Support is present"],"sort_order":165,"version":"funny"},{"id":"funny-166","prompt":"How can resistance build something instead of only yelling ''No''?","theme":"Joy, Resistance & Collective Change","answers":["Build alternatives","Care for people","Share resources","Create new habits"],"sort_order":166,"version":"funny"},{"id":"funny-167","prompt":"What keeps people coming back after the free snacks are gone?","theme":"Joy, Resistance & Collective Change","answers":["Belonging","Purpose","Achievable action","Enjoyment"],"sort_order":167,"version":"funny"},{"id":"funny-168","prompt":"What does healthy commitment include that heroic self-sacrifice forgets?","theme":"Joy, Resistance & Collective Change","answers":["Choice","Limits","Rest","Mutual support"],"sort_order":168,"version":"funny"},{"id":"funny-169","prompt":"When does a group get that ''Okay, we can actually do this'' feeling?","theme":"Joy, Resistance & Collective Change","answers":["They decide together","They act visibly","They protect one another","They see results"],"sort_order":169,"version":"funny"},{"id":"funny-170","prompt":"How can change improve life before the giant final victory arrives?","theme":"Joy, Resistance & Collective Change","answers":["New friendships","New skills","New routines","New confidence"],"sort_order":170,"version":"funny"},{"id":"funny-171","prompt":"What can make collective action feel like emotional first aid?","theme":"Joy, Resistance & Collective Change","answers":["Being heard","Sharing pain","Helping others","Making meaning"],"sort_order":171,"version":"funny"},{"id":"funny-172","prompt":"Why should a movement occasionally stop and throw a party?","theme":"Joy, Resistance & Collective Change","answers":["It remembers wins","It builds bonds","It restores energy","It welcomes newcomers"],"sort_order":172,"version":"funny"},{"id":"funny-173","prompt":"What’s the best emergency kit for social despair?","theme":"Joy, Resistance & Collective Change","answers":["Companionship","Visible progress","Practical action","Imagination"],"sort_order":173,"version":"funny"},{"id":"funny-174","prompt":"How do you make a huge goal feel less like climbing a mountain in flip-flops?","theme":"Joy, Resistance & Collective Change","answers":["It is ambitious","Part of it is achievable now","It is shared","It connects to daily life"],"sort_order":174,"version":"funny"},{"id":"funny-175","prompt":"How can a serious cause still make room for joy?","theme":"Joy, Resistance & Collective Change","answers":["Humor","Care","Creativity","Commitment"],"sort_order":175,"version":"funny"},{"id":"funny-176","prompt":"Your body wants to protest without making a speech. What can it do?","theme":"Joy, Resistance & Collective Change","answers":["Presence","Movement","Refusal","Endurance"],"sort_order":176,"version":"funny"},{"id":"funny-177","prompt":"What changes the second people take a private problem into public space?","theme":"Joy, Resistance & Collective Change","answers":["It becomes visible","It feels shared","It feels urgent","It feels hopeful"],"sort_order":177,"version":"funny"},{"id":"funny-178","prompt":"What’s the everyday version of resistance that doesn’t require a megaphone?","theme":"Joy, Resistance & Collective Change","answers":["A boundary","A conversation","Mutual aid","A small refusal"],"sort_order":178,"version":"funny"},{"id":"funny-179","prompt":"When courage runs low, where do people usually borrow more?","theme":"Joy, Resistance & Collective Change","answers":["Community","Preparation","Purpose","Past victories"],"sort_order":179,"version":"funny"},{"id":"funny-180","prompt":"What makes a movement feel alive instead of looking like an endless meeting agenda?","theme":"Joy, Resistance & Collective Change","answers":["People are learning","People are connecting","People are creating","People are acting"],"sort_order":180,"version":"funny"},{"id":"funny-181","prompt":"A better future has limited shelf space. What deserves the biggest section?","theme":"Future Society, Freedom & Human Limits","answers":["Time","Autonomy","Security","Connection"],"sort_order":181,"version":"funny"},{"id":"funny-182","prompt":"Robots are doing more work. What should humans get in return?","theme":"Future Society, Freedom & Human Limits","answers":["Shorter work hours","Shared wealth","Public services","Education"],"sort_order":182,"version":"funny"},{"id":"funny-183","prompt":"If GDP had to share the scoreboard, what should we measure too?","theme":"Future Society, Freedom & Human Limits","answers":["Wellbeing","Free time","Ecological health","Equality"],"sort_order":183,"version":"funny"},{"id":"funny-184","prompt":"Freedom sounds great until one basic thing is missing. What is it?","theme":"Future Society, Freedom & Human Limits","answers":["Money","Time","Support","Safe options"],"sort_order":184,"version":"funny"},{"id":"funny-185","prompt":"When is ''my choice'' actually a real choice instead of a menu with one option?","theme":"Future Society, Freedom & Human Limits","answers":["There are real alternatives","Information is good","Resources are available","Social support exists"],"sort_order":185,"version":"funny"},{"id":"funny-186","prompt":"Equality is not photocopying everyone. What does it actually require?","theme":"Future Society, Freedom & Human Limits","answers":["Fair access","Recognition of differences","Shared power","Material support"],"sort_order":186,"version":"funny"},{"id":"funny-187","prompt":"If society respected human limits, what would suddenly become normal?","theme":"Future Society, Freedom & Human Limits","answers":["Allow more rest","Slow the pace","Design better care","Reduce insecurity"],"sort_order":187,"version":"funny"},{"id":"funny-188","prompt":"Future cities can optimize one thing first. What should beat traffic flow and ad revenue?","theme":"Future Society, Freedom & Human Limits","answers":["People","Community","Environment","Accessibility"],"sort_order":188,"version":"funny"},{"id":"funny-189","prompt":"What’s the strongest seatbelt for a society using powerful technology?","theme":"Future Society, Freedom & Human Limits","answers":["Democratic control","Strong rights","Public alternatives","Transparent design"],"sort_order":189,"version":"funny"},{"id":"funny-190","prompt":"Humans get futuristic upgrades. What old-fashioned thing will probably still matter most?","theme":"Future Society, Freedom & Human Limits","answers":["Relationships","Meaning","Embodiment","Nature"],"sort_order":190,"version":"funny"},{"id":"funny-191","prompt":"Efficiency is impressive, but what actually makes a life feel worth living?","theme":"Future Society, Freedom & Human Limits","answers":["Purpose","Connection","Curiosity","Care"],"sort_order":191,"version":"funny"},{"id":"funny-192","prompt":"What has to change for social change to survive longer than a trending hashtag?","theme":"Future Society, Freedom & Human Limits","answers":["Institutions change","Habits change","Relationships change","Resources change"],"sort_order":192,"version":"funny"},{"id":"funny-193","prompt":"A choice wants to call itself ''free.'' What must it include?","theme":"Future Society, Freedom & Human Limits","answers":["Ability to say no","Ability to change your mind","Access to alternatives","Understanding the consequences"],"sort_order":193,"version":"funny"},{"id":"funny-194","prompt":"Everyone is vulnerable eventually. What would a humane society do with that fact?","theme":"Future Society, Freedom & Human Limits","answers":["See it as shared","Respond with care","Design around it","Build solidarity from it"],"sort_order":194,"version":"funny"},{"id":"funny-195","prompt":"What should make people uncomfortable the moment someone puts a price tag on it?","theme":"Future Society, Freedom & Human Limits","answers":["Care","Dignity","Belonging","Bodily autonomy"],"sort_order":195,"version":"funny"},{"id":"funny-196","prompt":"What goes wrong when humans are managed like very emotional spreadsheets?","theme":"Future Society, Freedom & Human Limits","answers":["Human limits get ignored","Meaning gets lost","Empathy gets reduced","Optimization never stops"],"sort_order":196,"version":"funny"},{"id":"funny-197","prompt":"When is technology doing its job instead of creating three new jobs for you?","theme":"Future Society, Freedom & Human Limits","answers":["It saves time","It expands access","It protects autonomy","It reduces drudgery"],"sort_order":197,"version":"funny"},{"id":"funny-198","prompt":"If society gave everyone a quality-of-life starter pack, what belongs inside?","theme":"Future Society, Freedom & Human Limits","answers":["Rest","Care","Participation","Creativity"],"sort_order":198,"version":"funny"},{"id":"funny-199","prompt":"What kind of wealth makes a billionaire’s calculator mostly useless?","theme":"Future Society, Freedom & Human Limits","answers":["Free time","Strong relationships","A healthy environment","Collective security"],"sort_order":199,"version":"funny"},{"id":"funny-200","prompt":"Every social system gets one brutally simple survey question. What should it be?","theme":"Future Society, Freedom & Human Limits","answers":["Who benefits?","Who decides?","Who bears the cost?","Who has real choices?"],"sort_order":200,"version":"funny"}]'::jsonb) r;